const response = await getCompanyApplyDetail(this.companyApplyId)
const data = response.data || {}
this.companyApply = data.companyApply || {}
this.bindingList = data.bindingList || []
this.attachments = data.attachments || []
// 法定代表人联系电话来源为企业档案（T_COMPANY.LEGAL_PERSON_PHONE）；
// 备案申请表 T_COMPANY_APPLY 本身不含该字段，/company/companyApply/detail 也未将其随企业档案关联返回，
// 因此需按公司备案记录 companyRecordId 单独回显。
const companyRecordId = this.companyApply.companyRecordId
if (companyRecordId) {
  try {
    const recordRes = await getCompanyRecordDetail(companyRecordId)
    const record = recordRes.data?.companyRecord || recordRes.data || {}
    const phone = record.legalPersonPhone
    if (phone != null && String(phone) !== '') {
      this.companyApply = { ...this.companyApply, legalPersonPhone: phone }
    }
  } catch (e) {
    // 联系电话回显失败不影响其余字段展示
  }
}
if (!this.isReviewing) this.approvalVisible = false

